// Generated by OrchestKit Claude Plugin
// Created: 2026-08-09 (#3317)

/**
 * Session turn counter — the one real per-turn count in the hook tree.
 *
 * `prompt/cache-break-detector` increments `turnCount` in its session state
 * file once per UserPromptSubmit. That is the only counter that advances with
 * conversational turns, so anything asking "how many turns has this session
 * taken" reads it from here instead of inventing a second mechanism.
 *
 * #3317: `stop/goal-tracker` used to derive a turn count by counting `/goal`
 * START lines in `goal-history.jsonl`. That counts INVOCATIONS, not turns, so
 * the Nth close recorded N and `lifecycle/goal-budget-guard` summed those into
 * 1+2+...+N. Eight one-turn `/goal` runs reported 36 turns and tripped a
 * ceiling meant for 30 real turns.
 *
 * The file is owned by cache-break-detector (the sole writer); this module is
 * the shared path + read side so the two never drift apart.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { getSessionStorageDir } from './paths.js';

/** State file within session storage. Written by prompt/cache-break-detector. */
export const TURN_STATE_FILE = 'cache-break-state.json';

/** Path to the session state file holding the turn counter. */
export function getTurnStateFilePath(sessionId: string): string {
  return join(getSessionStorageDir(), sessionId, TURN_STATE_FILE);
}

/**
 * Current turn count for a session. Returns 0 when no counter exists yet
 * (first turn, or the detector skipped every prompt so far) — callers treat
 * 0 as "no signal" rather than as a real zero.
 */
export function readTurnCount(sessionId: string): number {
  if (!sessionId) return 0;
  try {
    const path = getTurnStateFilePath(sessionId);
    if (!existsSync(path)) return 0;
    const parsed = JSON.parse(readFileSync(path, 'utf8')) as { turnCount?: unknown };
    const n = Number(parsed?.turnCount);
    return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
  } catch {
    return 0;
  }
}

/**
 * Turns spanned by a single run, counted inclusively: a run that starts and
 * ends on the same turn costs 1.
 *
 * `startedTurn` is the counter value captured when the run opened. A missing
 * or unusable baseline (legacy history rows written before #3317, or a session
 * whose counter never advanced) yields 1 — a run always costs at least the
 * turn it was requested on. Never returns 0 or a negative, so a counter reset
 * mid-session cannot subtract from the session budget.
 */
export function turnsSpanned(startedTurn: unknown, currentTurn: number): number {
  const started = Number(startedTurn);
  if (!Number.isFinite(started) || started <= 0) return 1;
  if (!Number.isFinite(currentTurn) || currentTurn < started) return 1;
  return Math.max(1, Math.floor(currentTurn) - Math.floor(started) + 1);
}
